273	// full track rather than as an unknown phase.
274	const phasesFor = (type, phase) =>
275	  type === "spike" && (!phase || SPIKE_PHASES.includes(String(phase))) ? SPIKE_PHASES : PHASES;
276	const KNOWN = new Set(["schema","title","branch","tier","phase","plan","scorecard","decisions","code","needs_you","waiting_on","links","session","worklog","complexity","type","children"]);
