278	/* ---------- minimal syntax highlighting (strings, comments, keywords, numbers) ---------- */
279	const KW = /\b(def|class|return|if|elif|else|for|while|import|from|as|with|try|except|finally|raise|lambda|yield|async|await|const|let|var|function|new|typeof|export|default|fn|pub|impl|struct|enum|match|use|mod|go|func|type|interface|package|nil|null|None|true|false|True|False|self|this)\b/g;
280	function hl(code) {
281	  let out = "", rest = esc(code);
282	  const tok = /("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|`(?:[^`\\]|\\.)*`|#[^\n]*|\/\/[^\n]*)/g;
283	  let last = 0, m;
284	  const plain = s => s.replace(KW, '<span class="hl-k">$1</span>')
285	                      .replace(/\b(\d+\.?\d*)\b/g, '<span class="hl-n">$1</span>');
286	  while ((m = tok.exec(rest))) {
287	    out += plain(rest.slice(last, m.index));
288	    const cls = (m[0][0] === "#" || m[0].startsWith("//")) ? "hl-c" : "hl-s";
289	    out += `<span class="${cls}">${m[0]}</span>`;
290	    last = m.index + m[0].length;
291	  }
292	  return out + plain(rest.slice(last));
293	}
