295	/* minimal markdown for worklog notes: headers, bullets, bold, inline code, fenced blocks. */
296	function md(src) {
297	  const parts = String(src).split(/^```.*$/m);
298	  let html = "";
299	  parts.forEach((part, i) => {
300	    if (i % 2) { html += `<pre>${hl(part.replace(/^\n|\n$/g, ""))}</pre>`; return; }
301	    const inline = s => esc(s)
302	      .replace(/`([^`]+)`/g, '<code>$1</code>')
303	      .replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
304	    let listOpen = false, out = [];
305	    for (const line of part.split("\n")) {
306	      const h = line.match(/^(#{1,6})\s+(.*)/);
307	      const li = line.match(/^\s*[-*]\s+(.*)/);
308	      if (li) { if (!listOpen) { out.push("<ul>"); listOpen = true; } out.push(`<li>${inline(li[1])}</li>`); continue; }
309	      if (listOpen) { out.push("</ul>"); listOpen = false; }
310	      if (h) out.push(`<h${h[1].length + 2}>${inline(h[2])}</h${h[1].length + 2}>`);
311	      else if (line.trim()) out.push(`<p>${inline(line)}</p>`);
312	    }
313	    if (listOpen) out.push("</ul>");
314	    html += out.join("");
315	  });
316	  return html;
317	}
