468	    `<div class="what"><b>${esc(e.trigger || "")}</b><small>${esc(sub)}</small></div>` +
469	    `<span class="go">${resolveBtn(e)}</span></div>` +
470	    (detail ? fold(`friction|${group}|${i}`, "detail", detail) : "");
471	}
