473	function frictionHTML() {
474	  const all = feedbackAll();
475	  if (!all.length) return "";
476	  const open = all.filter(e => !e.resolved), done = all.filter(e => e.resolved);
477	  const signals = [...new Set(open.map(e => e.signal))]
478	    .sort((a, b) => (SIG_ORDER.indexOf(a) + 1 || 99) - (SIG_ORDER.indexOf(b) + 1 || 99));
479	  const counts = signals.map(sig =>
480	    `<span class="chip">${esc(sig)} <b>${open.filter(e => e.signal === sig).length}</b></span>`).join("");
481	  const body =
482	    (counts ? `<div class="sigcounts">${counts}</div>` : "") +
483	    (open.length
484	      ? newestFirst(open).map((e, i) => frictionRow(e, i, "open")).join("")
485	      : `<div class="calm">all captured friction reviewed</div>`) +
486	    (done.length
487	      ? `<div class="resolvedwrap">` + fold("board|frictiondone", `Resolved · ${done.length}`,
488	          newestFirst(done).map((e, i) => frictionRow(e, i, "done")).join("")) + `</div>`
489	      : "");
490	  return `<section class="bandfold friction">` +
491	    fold("board|friction", `Friction · ${open.length}`, body) + `</section>`;
492	}
