495	function statsHTML() {
496	  const ts = flat().filter(x => !x.t.error && !isArchived(x.t));
497	  const inFlight = ts.filter(x => (x.t.task.phase || "") !== "done").length;
498	  const need = ts.filter(x => (x.t.task.phase || "") !== "done").reduce((a, x) => a + needsCount(x.t), 0);
499	  const waiting = ts.filter(x => (x.t.task.phase || "") !== "done").reduce((a, x) => a + waitCount(x.t), 0);
500	  const stale = ts.filter(x => (x.t.task.phase || "") !== "done" && isStale(x.t.mtime)).length;
501	  const friction = feedbackOpen().length;
502	  return `<div class="stat"><b>${inFlight}</b><span>in flight</span></div>` +
503	    (need ? `<div class="stat attn"><b>${need}</b><span>need you</span></div>` : "") +
504	    (waiting ? `<div class="stat wait"><b>${waiting}</b><span>waiting on</span></div>` : "") +
505	    (stale ? `<div class="stat"><b>${stale}</b><span>stale</span></div>` : "") +
506	    (friction ? `<div class="stat"><b>${friction}</b><span>friction</span></div>` : "");
507	}
