622	/* taskBodyHTML renders the narrative (left) and status-rail (right)
623	   sections for one "task-like" object — a plain ticket's k, or one
624	   epic child entry — parameterized by fk so fold keys never collide
625	   across children. */
626	function taskBodyHTML(k, fk) {
627	  let left = "";
628	  if (Array.isArray(k.needs_you) && k.needs_you.length) {
629	    left += `<div class="sec warn"><h3>Needs you <span class="count">${k.needs_you.length}</span></h3>` +
630	      k.needs_you.map((n, i) => {
631	        const type = esc(n.type || "item");
632	        return `<div class="need"><span class="kind ${type}">${type}</span>` +
633	          `<div class="what"><b>${esc(n.text || "")}</b></div></div>` +
634	          (n.detail ? fold(fk("needs" + i), "detail", `<pre>${hl(String(n.detail))}</pre>`) : "");
635	      }).join("") + `</div>`;
636	  }
637	  if (Array.isArray(k.waiting_on) && k.waiting_on.length) {
638	    left += `<div class="sec waitsec"><h3>Waiting on <span class="count">${k.waiting_on.length}</span></h3>` +
639	      k.waiting_on.map((w, i) =>
640	        `<div class="need"><span class="kind wait">${esc(w.who || "?")}</span>` +
641	        `<div class="what"><b>${esc(w.text || "")}</b></div>` +
642	        `<span class="go">${w.link ? `<a class="asklink" href="${esc(safeHref(w.link))}" target="_blank" rel="noopener">↗ asked</a> ` : ""}${ageChip(w.asked)}</span></div>` +
643	        (w.detail ? fold(fk("wait" + i), "detail", `<pre>${hl(String(w.detail))}</pre>`) : "")
644	      ).join("") + `</div>`;
645	  }
646	  if (Array.isArray(k.decisions) && k.decisions.length) {
647	    left += `<div class="sec"><h3>Decisions <span class="count">${k.decisions.length}</span></h3><div class="tl">` +
648	      k.decisions.map(dRaw => {
649	        const d = itemText(dRaw);
650	        return `<div class="ev"><b>${esc(d.what || d.text || "")}</b>` +
651	          (d.why ? `<small>${esc(d.why)}</small>` : "") +
652	          (d.when ? `<span class="when">${esc(d.when)}</span>` : "") + `</div>`;
653	      }).join("") + `</div></div>`;
654	  }
655	  if (Array.isArray(k.code) && k.code.length) {
656	    left += `<div class="sec"><h3>Code to know <span class="count">${k.code.length}</span></h3>` +
657	      k.code.map((c, i) =>
658	        `<div class="codeblock"><span class="path">${esc(c.file || "")}${c.lines ? ":" + esc(c.lines) : ""}</span>` +
659	        (c.lang ? `<span class="lang">${esc(c.lang)}</span>` : "") +
660	        (c.note ? `<div class="note">${esc(c.note)}</div>` : "") +
661	        (c.snippet ? fold(fk("code" + i), "snippet", `<pre>${hl(String(c.snippet))}</pre>`) : "") + `</div>`).join("") + `</div>`;
662	  }
663	
664	  let right = "";
665	  if (Array.isArray(k.plan) && k.plan.length) {
666	    const { done, total } = planStats(k.plan);
667	    right += `<div class="sec"><h3>Plan <span class="count">${done}/${total}</span></h3><ul class="plain">` +
668	      k.plan.map(pRaw => {
669	        const p = itemText(pRaw), st = p.state || "pending";
670	        return `<li class="${esc(st)}"><span class="mk">${mark(st)}</span><span class="tx">${esc(p.text || "")}</span></li>`;
671	      }).join("") + `</ul></div>`;
672	  }
673	  if (Array.isArray(k.scorecard) && k.scorecard.length) {
674	    const passed = k.scorecard.filter(c => itemText(c).status === "pass").length;
675	    right += `<div class="sec"><h3>Contract scorecard <span class="count">${passed}/${k.scorecard.length}</span></h3><ul class="plain">` +
676	      k.scorecard.map(cRaw => {
677	        const c = itemText(cRaw), st = c.status || "pending";
678	        return `<li class="${esc(st)}"><span class="mk">${mark(st)}</span><span><span class="tx">${esc(c.text || "")}</span>` +
679	          (c.verify ? `<span class="vf">verify: ${esc(c.verify)}</span>` : "") + `</span></li>`;
680	      }).join("") + `</ul></div>`;
681	  }
682	  if (Array.isArray(k.links) && k.links.length) {
683	    right += `<div class="sec"><h3>Links</h3><ul class="plain">` + k.links.map(lRaw => {
684	      const l = itemText(lRaw);
685	      return `<li><span class="mk pending">↗</span><a href="${esc(safeHref(l.url || "#"))}" target="_blank" rel="noopener">${esc(l.label || l.url || l.text || "")}</a></li>`;
