691	const CHILD_BADGE = { active: "▶ active", pending: "○ pending", done: "✓ done" };
692	
693	/* one collapsible section per epic child, each with its own independent
694	   plan/scorecard/decisions/code/needs-you/waiting-on — never the shared
695	   top-level fields the plain-ticket path reads, since those are unused
696	   on an epic file (see devboard/schema.md's "Epic files"). */
697	function childrenDetailHTML(children, hash) {
698	  if (!children.length) {
699	    return `<div class="sec"><div class="calm childrenempty">no children started yet</div></div>`;
700	  }
701	  const sorted = children.slice().sort((a, b) => (CHILD_ORDER[a.state] ?? 1) - (CHILD_ORDER[b.state] ?? 1));
702	  return sorted.map(c => {
703	    const st = c.state || "pending";
704	    const cfk = s => `${hash}|child|${c.id}|${s}`;
705	    const { left: cl, right: cr } = taskBodyHTML(c, cfk);
706	    const inner = (cl || cr)
707	      ? `<div class="cols childcols">${cl ? `<div>${cl}</div>` : ""}${cr ? `<div>${cr}</div>` : ""}</div>`
708	      : `<div class="calm" style="margin:0">nothing recorded yet</div>`;
709	    return `<div class="sec childsec"><h3>${esc(c.title || c.id)} ` +
710	      `<span class="count child-${st}">${CHILD_BADGE[st] || st}</span></h3>` +
711	      (c.branch || c.phase ? `<div class="fnote">${c.branch ? "⎇ " + esc(c.branch) : ""}${c.branch && c.phase ? " · " : ""}${c.phase ? esc(c.phase) : ""}</div>` : "") +
712	      inner + `</div>`;
713	  }).join("");
714	}
