716	function viewDetail(hash) {
717	  const [repo, id] = hash.split("/");
718	  const r = DB.repos.find(x => x.repo === repo);
719	  const t = r?.tasks.find(x => x.id === id);
720	  const crumb = `<a class="crumb" href="#">← all tasks</a>`;
721	  if (!t) return `${crumb}<div class="empty">Task <code>${esc(hash)}</code> not found (removed?).</div>`;
722	  if (t.error) return `${crumb}<div class="sec errcard"><h3>parse error</h3><div class="msg">${esc(t.error)}</div></div>`;
723	  const k = t.task, fk = s => `${hash}|${s}`, epic = k.type === "epic";
724	
725	  let html = crumb + `<div class="hero"><h1>${esc(k.title || t.id)}</h1><div class="metarow">` +
726	    `<span class="chip">${esc(repo)}</span>` +
727	    (epic ? `<span class="chip epicbadge">◆ epic</span>` : "") +
728	    (k.type === "spike" ? `<span class="chip spikebadge">◇ spike</span>` : "") +
729	    (!epic && k.branch ? `<span class="chip">⎇ ${esc(k.branch)}</span>` : "") +
730	    (!epic && k.tier !== undefined ? `<span class="chip">tier ${esc(k.tier)}${k.complexity ? " · cx " + esc(k.complexity) : ""}</span>` : (!epic && k.complexity ? `<span class="chip">cx ${esc(k.complexity)}</span>` : "")) +
731	    (k.worklog ? `<span class="chip">☰ ${esc(k.worklog)}</span>` : "") +
732	    (t.mtime ? `<span class="chip">${ago(t.mtime)}</span>` : "") +
733	    (isArchived(t) ? `<span class="chip archchip">archived</span>` : "") +
734	    resumeBtn(k, "⧉ claude --resume") + " " + moveBtn(repo, t) +
735	    `</div>` + (epic ? "" : stepperHTML(k.phase, k.type)) + `</div>`;
736	
737	  let left = "", right = "";
738	  if (epic) {
739	    left = childrenDetailHTML(k.children || [], hash);
740	  } else {
741	    ({ left, right } = taskBodyHTML(k, fk));
742	    const extra = Object.keys(k).filter(key => !KNOWN.has(key));
743	    if (extra.length) {
744	      right += `<div class="sec"><h3>Other</h3><table class="kv">` + extra.map(key =>
745	        `<tr><td>${esc(key)}</td><td>${esc(typeof k[key] === "object" ? JSON.stringify(k[key], null, 1) : k[key])}</td></tr>`).join("") +
746	        `</table></div>`;
747	    }
748	  }
749	
750	  html += (left && right) ? `<div class="cols"><div>${left}</div><div>${right}</div></div>` : (left || right);
751	  if (t.notes) {
752	    html += `<div class="sec">` + fold(fk("notes"),
753	      `Worklog notes${k.worklog ? " · " + esc(k.worklog) : ""}`,
754	      `<div class="mdbody">${md(t.notes)}</div>`) + `</div>`;
755	  }
756	  return html;
757	}
