759	/* ---------- render with fold + scroll persistence ---------- */
760	function bindFolds() {
761	  document.querySelectorAll("details[data-k]").forEach(d => {
762	    if (openFolds.has(d.dataset.k)) d.open = true;
763	    d.addEventListener("toggle", () =>
764	      d.open ? openFolds.add(d.dataset.k) : openFolds.delete(d.dataset.k));
765	  });
766	}
767	function render() {
768	  const hash = decodeURIComponent(location.hash.slice(1));
769	  const y = window.scrollY;
770	  $stats.innerHTML = statsHTML();
771	  $app.innerHTML = hash ? viewDetail(hash) : viewBoard();
772	  bindFolds();
773	  window.scrollTo(0, hash === lastHash ? y : 0);   // live reload keeps place; navigation goes to top
774	  lastHash = hash;
775	}
776	
777	/* ---------- data + hot reload ---------- */
778	async function refresh() {
779	  try {
780	    const res = await fetch("/api/tasks", { cache: "no-store" });
781	    DB = await res.json();
782	    render();
783	  } catch (e) { /* server briefly away; SSE reconnect will retrigger */ }
784	}
785	function connect() {
786	  const es = new EventSource("/events");           // EventSource auto-reconnects
787	  es.onopen = () => { $conn.textContent = "live"; $conn.className = "live"; refresh(); };
788	  es.onmessage = refresh;
789	  es.onerror = () => { $conn.textContent = "reconnecting…"; $conn.className = "down"; };
790	}
791	window.addEventListener("hashchange", render);
792	connect();
793	refresh();
794	</script>
795	</body>
796	</html>
